== README.md
# settings

`node src/app.js [config.json]` starts the app with the settings in the file. A file that is not valid JSON stops it with `bad config: <message>` and exit 1.

Tests: `npm test`.
== package.json
{
  "name": "settings",
  "version": "1.0.0",
  "description": "Loads the app settings",
  "type": "module",
  "main": "index.js",
  "scripts": {
    "test": "node --test"
  },
  "license": "MIT"
}
== src/app.js
#!/usr/bin/env node
import { loadConfig } from './config.js';

const DEFAULTS = { port: 8080, greeting: 'hi' };
let config;
try {
  config = { ...DEFAULTS, ...loadConfig(process.argv[2] ?? 'config.json') };
} catch (error) {
  process.stderr.write(`bad config: ${error.message}\n`);
  process.exit(1);
}
process.stdout.write(`listening on ${config.port}\n`);
== src/config.js
import { readFileSync } from 'node:fs';

/** The settings in a JSON file. */
export function loadConfig(path) {
  return JSON.parse(readFileSync(path, 'utf8'));
}
== test/config.test.js
import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { loadConfig } from '../src/config.js';

const file = (text) => {
  const f = join(mkdtempSync(join(tmpdir(), 'cfg-')), 'config.json');
  writeFileSync(f, text);
  return f;
};

test('reads a config', () => assert.deepEqual(loadConfig(file('{"port": 9000}')), { port: 9000 }));
test('bad JSON throws', () => assert.throws(() => loadConfig(file('{port: 9000')), SyntaxError));

